package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import android.text.Spanned;import android.text.style.ForegroundColorSpan;import com.google.android.gms.tasks.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;

/** Real on-device HY-MT inference, multilingual planning and translated source highlighting. */
public class HunyuanTranslationTest extends VoiceWarmupTest {
    static final String[][] SAMPLES={
        {"en","The little horse is reading a book by the window. The warm sunlight falls gently on the pages."},
        {"ja","小さな馬が窓辺で本を読んでいます。暖かい日差しがページを優しく照らしています。"},
        {"ko","작은 말이 창가에서 책을 읽고 있습니다. 따뜻한 햇빛이 책장을 부드럽게 비춥니다."},
        {"fr","Le petit cheval lit un livre près de la fenêtre. La lumière du soleil éclaire doucement les pages."},
        {"de","Das kleine Pferd liest ein Buch am Fenster. Das warme Sonnenlicht fällt sanft auf die Seiten."},
        {"es","El pequeño caballo lee un libro junto a la ventana. La cálida luz del sol ilumina las páginas."},
        {"pt","O pequeno cavalo lê um livro junto à janela. A luz quente do sol ilumina suavemente as páginas."},
        {"ru","Маленькая лошадка читает книгу у окна. Тёплый солнечный свет мягко освещает страницы."},
        {"ar","يقرأ الحصان الصغير كتابًا بجانب النافذة. تضيء أشعة الشمس الدافئة صفحات الكتاب بلطف."},
        {"hi","छोटा घोड़ा खिड़की के पास एक किताब पढ़ रहा है। सूरज की गर्म रोशनी किताब के पन्नों पर पड़ रही है।"},
        {"id","Kuda kecil sedang membaca buku di dekat jendela. Sinar matahari yang hangat menyinari halaman buku."},
        {"vi","Chú ngựa nhỏ đang đọc sách bên cửa sổ. Ánh nắng ấm áp nhẹ nhàng chiếu lên những trang sách."},
        {"th","ม้าตัวเล็กกำลังอ่านหนังสืออยู่ข้างหน้าต่าง แสงแดดอันอบอุ่นส่องลงบนหน้าหนังสืออย่างอ่อนโยน"}
    };
    void stage(String message){Bundle status=new Bundle();status.putString("stage",message);sendStatus(1,status);}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;OfflineTranslation translation=new OfflineTranslation(getTargetContext());SharedPreferences prefs=getTargetContext().getSharedPreferences("reading_settings",0);Map<String,?> saved=new HashMap<>(prefs.getAll());boolean success=false;
        try{
            check(Tasks.await(translation.available(),5,TimeUnit.SECONDS),"Import HY-MT model first");check(HunyuanModels.get(getTargetContext()).ready(),"Model missing");
            for(String[] sample:SAMPLES){long started=SystemClock.elapsedRealtime();String heading=Locale.forLanguageTag(sample[0]).getDisplayLanguage(Locale.ENGLISH);String source=heading+"\n"+sample[1];OfflineTranslation.Session session=translation.session(Collections.singletonList(sample[1]),"zh",source,Collections.singletonList(heading.length()+1));String output=session.get(0);check(output.codePoints().anyMatch(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.HAN),"Not Chinese: "+sample[0]+" -> "+output);check(!output.equals(sample[1]),"Untranslated: "+sample[0]);result.putString(sample[0]+"ToChinese",output);stage(sample[0]+" -> zh "+(SystemClock.elapsedRealtime()-started)+" ms: "+output);}
            for(String target:new String[]{"en","ja"}){OfflineTranslation.Session session=translation.session(Collections.singletonList("小马正在窗边看书。温暖的阳光照在书页上。"),target);String output=session.get(0);check(!output.isEmpty()&&!output.equals(session.source.get(0)),"Reverse translation unchanged");if(target.equals("ja"))check(output.codePoints().anyMatch(c->Character.UnicodeScript.of(c)==Character.UnicodeScript.HIRAGANA||Character.UnicodeScript.of(c)==Character.UnicodeScript.KATAKANA),"Not Japanese");result.putString("ChineseTo"+target,output);stage("zh -> "+target+": "+output);}
            String direct=Tasks.await(translation.translate("ja","de",SAMPLES[1][1]),60,TimeUnit.SECONDS);check(direct.matches("(?s).*[A-Za-z].*")&&!direct.contains("小さな"),"Japanese to German failed");result.putString("JapaneseToGerman",direct);
            OfflineTranslation.Session chinese=translation.session(Collections.singletonList("小马正在安静地读书。"),"zh");check(chinese.get(0).equals("小马正在安静地读书。"),"Original Chinese was rewritten");OfflineTranslation.Session traditional=translation.session(Collections.singletonList("小馬正在安靜地讀書。"),"zh");check(traditional.get(0).equals("小馬正在安靜地讀書。"),"Traditional Chinese changed unnecessarily");
            OfflineTranslation.Session cancelled=translation.session(Collections.singletonList("A quiet village lies beneath the mountains. "+SAMPLES[0][1]+SAMPLES[0][1]),"zh");AtomicReference<Throwable> cancelledError=new AtomicReference<>();Thread computation=new Thread(()->{try{cancelled.get(0);}catch(Throwable failure){cancelledError.set(failure);}});computation.start();await(()->HunyuanEngine.get(getTargetContext()).busy(),"Cancellation fixture did not start",5000);check(!HunyuanModels.get(getTargetContext()).delete().isSuccessful(),"Active model deleted");cancelled.cancel();computation.join(6000);check(!computation.isAlive()&&cancelledError.get()!=null,"Cancelled inference kept running");await(()->!HunyuanEngine.get(getTargetContext()).busy(),"Cancelled native inference retained CPU",6000);stage("native cancellation and active-model delete guard passed");
            activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","hunyuan_reading_qa").putExtra("book_name","混元离线译读验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.system!=null&&a.system.initialized,"System voice unavailable",30000);ui(()->{SystemSpeaker.Option voice=a.system.offlineVoice("zh","");check(voice!=null,"Chinese system voice missing");a.readingLanguage="zh";a.systemVoiceKey=voice.key;prefs.edit().putString(MainActivity.readingVoicePreference("zh"),voice.key).commit();a.text="第一章 混元译读\n"+SAMPLES[0][1]+"\n"+SAMPLES[1][1]+"\n"+SAMPLES[2][1]+"\n";a.chapters=MainActivity.parse(a.text);a.position=0;a.rate=1.3f;a.loopPlayback=false;a.showPosition(true);a.startReading();});
            int body=a.text.indexOf("The little");await(()->a.playing&&a.position>=body&&a.latestStatus.contains("HY-MT1.5"),"Translated speech did not advance",45000);ui(()->{check(a.translatedSession!=null&&a.latestHighlightStart>=body,"Source highlight missing");Spanned shown=(Spanned)a.content.getText();check(shown.getSpans(0,shown.length(),ForegroundColorSpan.class).length>0,"Highlight span absent");check(a.languageProgress==null&&a.translationModelsDialog==null,"Old language-pack dialog appeared");a.stop(false);});int paused=a.position;
            ui(a::startReading);await(()->a.playing&&a.latestHighlightStart>=paused&&a.latestStatus.contains("HY-MT1.5"),"Translated pause/resume failed",30000);ui(a::stop);long highlighted=a.highlightUpdates;Thread.sleep(500);ui(()->check(a.highlightUpdates==highlighted,"Stale highlight after cancellation"));
            result.putLong("modelLoadMs",HunyuanEngine.get(getTargetContext()).lastLoadMs);result.putLong("lastTranslationMs",HunyuanEngine.get(getTargetContext()).lastTranslationMs);result.putString("result","PASS: actual local HY-MT translation from 13 foreign languages to Chinese plus simplified/traditional passthrough; Chinese to English/Japanese; Japanese directly to German; native cancellation and delete guard; Chinese speech with source highlights; pause/resume; no legacy language-pack download");success=true;
        }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));if(activity!=null)result.putString("reader",activity.latestStatus+" / "+activity.position);}
        finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}translation.close();restore(prefs,saved);getTargetContext().getSharedPreferences("reader_hunyuan_reading_qa",0).edit().clear().commit();new File(getTargetContext().getFilesDir(),"book_hunyuan_reading_qa.txt.position").delete();}
        finish(success?-1:0,result);
    }
}
